INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'brown-sugar-crockpot-ham', 'Brown Sugar Crockpot Ham.', NULL, 'Spiral-cut ham warmed in a caramelized brown sugar, maple syrup, and pineapple glaze until sweet, sticky, and fork tender.', NULL, 'beef-pork', '["ham","pork","slow cooker","holiday meal","entertaining"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Glazed spiral cut ham with caramelized brown sugar crust on a holiday platter', '[]', 10, 240, NULL, 'Low 3.5 to 4.5 hours',
  10, 'servings', '[{"quantity":7.5,"unit":"lb","item":"Bone-in spiral-cut ham","note":"Fully cooked, bone-in fits best in 6-to-7-quart oval cookers","scale":true},{"quantity":1,"unit":"cup","item":"Dark brown sugar","note":"Packed","scale":true},{"quantity":0.5,"unit":"cup","item":"Pure maple syrup","scale":true},{"quantity":0.5,"unit":"cup","item":"Pineapple juice","scale":true},{"quantity":2,"unit":"tbsp","item":"Dijon mustard","scale":true},{"quantity":1,"unit":"tbsp","item":"Apple cider vinegar","scale":true},{"quantity":0.25,"unit":"tsp","item":"Ground cloves","scale":true},{"quantity":0.5,"unit":"tsp","item":"Ground cinnamon","scale":true}]', '[{"title":"Step 1 – Fit the ham in the slow cooker","text":"Discard the plastic packaging, bone guard, and any commercial seasoning packet. Place the ham cut-side down into an oval 6-quart or 7-quart slow cooker. If the lid does not close fully, seal the top with a double layer of heavy-duty aluminum foil before placing the lid on top."},{"title":"Step 2 – Whisk the brown sugar glaze","text":"In a small saucepan over medium-low heat, stir the brown sugar, maple syrup, pineapple juice, Dijon mustard, apple cider vinegar, ground cloves, and cinnamon together until the sugar dissolves completely into a smooth syrup."},{"title":"Step 3 – Baste the ham","text":"Pour half of the warm glaze evenly over the ham, gently separating the spiral slices with a butter knife so the syrup penetrates deep between layers."},{"title":"Step 4 – Slow cook on Low","text":"Cover tightly and cook on Low for 3.5 to 4.5 hours (approx. 25-30 minutes per pound). Because the ham is already cured and cooked, your goal is to heat it gently through to an internal temperature of 140°F (60°C)."},{"title":"Step 5 – Glaze and caramelize","text":"During the final 30 minutes, baste the ham with the cooker juices and pour the remaining glaze over the exterior. For extra sticky crust, transfer to a roasting pan and broil in the oven for 3 minutes until bubbling and caramelized."}]', '["Spoon the sweet and savory pan juices over slices before serving.","Pair with scalloped potatoes, buttery dinner rolls, and crisp green salad."]', '["Never cook a spiral-cut ham on High; high heat will dry out the pre-cut slices and leach out all the natural moisture.","Save the meaty ham bone for making homemade slow cooker split pea or white bean soup."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Ovens often dry out spiral hams because the cut slices allow moisture to evaporate into the dry baking chamber. In the sealed, moist environment of a slow cooker, the ham gently warms in its own juices while absorbing the spiced brown sugar and pineapple glaze, keeping every single slice luscious and tender.', '2026-10-30', '2026-11-01', '2026-10-30T00:00:00.000Z', '2026-11-01T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
