INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'creamy-tuscan-chicken', 'Easy Crockpot Meals: Creamy Tuscan Chicken', NULL, 'Tender chicken breasts simmered in a velvety garlic Parmesan cream sauce with sweet sun-dried tomatoes and tender baby spinach.', NULL, 'slow-cooker-chicken', '["chicken","tuscan chicken","creamy chicken","slow cooker","easy dinners","weeknight"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Creamy Tuscan chicken in a slow cooker with sun-dried tomatoes and spinach', '[]', 15, 240, NULL, 'Low 3.5 to 4 hours (add dairy in the last 30 minutes)',
  4, 'servings', '[{"quantity":2,"unit":"lb","item":"Boneless skinless chicken breasts","note":"Or boneless chicken thighs","scale":true},{"quantity":1,"unit":"tsp","item":"Italian seasoning","scale":true},{"quantity":1,"unit":"tsp","item":"Garlic powder","scale":true},{"quantity":1,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Black pepper","scale":true},{"quantity":0.5,"unit":"cup","item":"Low-sodium chicken broth","scale":true},{"quantity":0.75,"unit":"cup","item":"Sun-dried tomatoes in oil","note":"Drained and thinly sliced","scale":true},{"quantity":4,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":0.75,"unit":"cup","item":"Heavy whipping cream","note":"Or full-fat cream cheese (4 oz cubed)","scale":true},{"quantity":0.5,"unit":"cup","item":"Freshly grated Parmesan cheese","scale":true},{"quantity":1,"unit":"tbsp","item":"Cornstarch","note":"Mixed with 1 tbsp water","scale":true},{"quantity":3,"unit":"cups","item":"Fresh baby spinach","note":"Packed","scale":true}]', '[{"title":"Step 1 – Season the chicken","text":"Pat the chicken breasts dry with paper towels. Season both sides with Italian seasoning, garlic powder, kosher salt, and black pepper."},{"title":"Step 2 – Layer into the crockpot","text":"Place the seasoned chicken in a single layer into the bottom of the slow cooker. Scatter the minced garlic and sliced sun-dried tomatoes over and around the chicken. Pour the chicken broth around the sides."},{"title":"Step 3 – Cook until tender","text":"Cover and cook on Low for 3 to 3.5 hours until the internal temperature of the chicken registers 165°F (74°C) with an instant-read meat thermometer."},{"title":"Step 4 – Whisk in the creamy sauce","text":"During the last 30 minutes of cooking, stir in the heavy cream, grated Parmesan cheese, and cornstarch slurry. Mix gently around the chicken until combined."},{"title":"Step 5 – Fold in the spinach","text":"Add the baby spinach on top, cover, and let cook for 10 minutes until the spinach wilts into the creamy sauce. Stir gently, taste, and adjust salt and pepper before serving."}]', '["Spoon the chicken and creamy sun-dried tomato sauce over cooked fettuccine, penne pasta, or mashed cauliflower for a low-carb dinner.","Serve with warm garlic bread to soak up the luxurious Parmesan cream sauce."]', '["Never add the heavy cream or cream cheese at the beginning of the cook cycle: dairy breaks and curdles over several hours of heat. Always add dairy in the final 30 minutes.","Using sun-dried tomatoes packed in olive oil gives superior tender texture compared to dry-packed tomatoes."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Creamy chicken recipes in a slow cooker often curdle if dairy is cooked from the start. By simmering the chicken and sun-dried tomatoes in seasoned broth first, then stirring in heavy cream, freshly grated Parmesan, and cornstarch in the final half-hour, you get an ultra-silky, rich sauce with chicken that is juicy and fork-tender.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
