INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'garlic-butter-slow-cooker-chicken-breast', 'Garlic Butter Slow Cooker Chicken Breast', NULL, 'Plump, tender boneless chicken breasts cooked in a rich garlic herb butter sauce. Never dry, easily shredded, and perfect over pasta, rice, or greens.', NULL, 'slow-cooker-chicken', '["chicken","chicken breast","garlic butter","slow cooker","easy dinners","low carb"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Juicy sliced garlic butter chicken breasts garnished with chopped parsley in a skillet', '[]', 10, 210, NULL, 'Low 3 to 3.5 hours (avoid cooking past 165°F)',
  4, 'servings', '[{"quantity":2,"unit":"lb","item":"Boneless skinless chicken breasts","note":"About 3 to 4 uniform breasts","scale":true},{"quantity":5,"unit":"tbsp","item":"Unsalted butter","note":"Melted","scale":true},{"quantity":6,"unit":"cloves","item":"Garlic","note":"Minced finely","scale":true},{"quantity":0.33,"unit":"cup","item":"Low-sodium chicken broth","scale":true},{"quantity":1,"unit":"tbsp","item":"Fresh lemon juice","scale":true},{"quantity":1,"unit":"tsp","item":"Italian seasoning","scale":true},{"quantity":1,"unit":"tsp","item":"Onion powder","scale":true},{"quantity":1,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Crushed red pepper flakes","note":"Optional for slight warmth","scale":true},{"quantity":0.5,"unit":"tsp","item":"Fresh ground black pepper","scale":true},{"quantity":2,"unit":"tbsp","item":"Fresh chopped Italian parsley","note":"For garnish","scale":true}]', '[{"title":"Step 1 – Season the chicken","text":"Pat the chicken breasts dry with paper towels. Season both sides with the salt, black pepper, onion powder, and Italian seasoning."},{"title":"Step 2 – Whisk the garlic butter sauce","text":"In a bowl or liquid measuring cup, whisk together the melted butter, minced garlic, chicken broth, lemon juice, and red pepper flakes."},{"title":"Step 3 – Arrange in cooker","text":"Place the seasoned chicken breasts in a single layer in the bottom of the slow cooker without overlapping. Pour the garlic butter mixture evenly over every piece."},{"title":"Step 4 – Cook on Low and monitor temperature","text":"Cover and cook on Low for 3 to 3.5 hours. Check with an instant-read meat thermometer in the thickest breast starting at the 3-hour mark. Remove the chicken promptly once it hits 165°F (74°C) to prevent drying."},{"title":"Step 5 – Rest and spoon sauce","text":"Transfer the chicken breasts to a cutting board and let rest for 5 minutes. Slice into thick strips or shred with two forks, then spoon the garlic butter pan juices generously over the top."}]', '["Serve over hot cooked angel hair pasta, creamy polenta, or steamed jasmine rice.","Toss with roasted asparagus or a fresh Caesar salad for a complete weeknight meal."]', '["Never cook boneless chicken breasts all day on Low (6-8 hours); chicken breast is very lean and will turn chalky and dry. 3 to 3.5 hours on Low is the sweet spot.","Use an instant-read digital thermometer. Pulling poultry at exactly 165°F guarantees moist, shreddable meat."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Boneless skinless chicken breasts have virtually no fat to protect them from high heat, making them prone to dryness in slow cookers. By keeping the cooking time strictly under 3.5 hours on Low, and basting the breasts continuously in real butter and fresh garlic broth, the meat cooks gently and retains its natural juices.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
