INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'healthy-slow-cooker-vegetable-minestrone', 'Healthy Slow Cooker Vegetable Minestrone', NULL, 'A nourishing Italian vegetable soup loaded with cannellini beans, zucchini, carrots, rich tomato broth, and finished with baby spinach and pasta.', NULL, 'vegetarian', '["vegetarian","minestrone","vegetable soup","healthy","slow cooker","soups and stews"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Vibrant slow cooker minestrone soup topped with freshly grated Parmesan and basil', '[]', 20, 360, NULL, 'Low 6 to 7 hours or High 3 to 4 hours',
  6, 'servings', '[{"quantity":1,"unit":"medium","item":"Yellow onion","note":"Diced","scale":true},{"quantity":3,"unit":"medium","item":"Carrots","note":"Sliced into half-moons","scale":true},{"quantity":2,"unit":"stalks","item":"Celery","note":"Chopped","scale":true},{"quantity":4,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":1,"unit":"can (28 oz)","item":"Crushed San Marzano tomatoes","scale":true},{"quantity":1,"unit":"can (15 oz)","item":"Cannellini beans (white kidney beans)","note":"Rinsed and drained","scale":true},{"quantity":1,"unit":"can (15 oz)","item":"Red kidney beans","note":"Rinsed and drained","scale":true},{"quantity":5,"unit":"cups","item":"Low-sodium vegetable broth","scale":true},{"quantity":1,"unit":"medium","item":"Zucchini","note":"Diced into bite-sized chunks","scale":true},{"quantity":1,"unit":"cup","item":"Fresh or frozen cut green beans","scale":true},{"quantity":1,"unit":"tbsp","item":"Italian seasoning","scale":true},{"quantity":1,"unit":"piece","item":"Parmesan cheese rind","note":"Optional, adds tremendous savory depth","scale":true},{"quantity":1.5,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Black pepper","scale":true},{"quantity":1,"unit":"cup","item":"Small pasta (ditalini, elbow, or small shells)","note":"Cooked separately or added during last 30 minutes","scale":true},{"quantity":2,"unit":"cups","item":"Fresh baby spinach","note":"Coarsely chopped","scale":true},{"quantity":0.25,"unit":"cup","item":"Freshly grated Parmesan cheese","note":"For serving","scale":true}]', '[{"title":"Step 1 – Combine base ingredients","text":"In the slow cooker basin, add the diced onion, carrots, celery, minced garlic, crushed tomatoes, cannellini beans, red kidney beans, vegetable broth, Italian seasoning, salt, black pepper, and the Parmesan rind."},{"title":"Step 2 – Slow cook on Low","text":"Cover and cook on Low for 5.5 to 6.5 hours (or High for 3 hours) until the root vegetables are tender and sweet."},{"title":"Step 3 – Add tender greens and pasta","text":"During the last 30 minutes of cooking, stir in the diced zucchini, green beans, and pasta. Cover and cook on High until the pasta is al dente and zucchini is tender."},{"title":"Step 4 – Wilt the spinach","text":"Discard the Parmesan rind. Stir in the fresh baby spinach and allow it to wilt in the hot broth for 2 minutes. Taste and adjust salt or add a squeeze of fresh lemon juice for brightness."},{"title":"Step 5 – Serve warm","text":"Ladle into wide soup bowls and top generously with freshly grated Parmesan cheese and torn basil leaves."}]', '["Serve with crusty garlic bread or warm focaccia for dipping into the rich tomato broth.","Drizzle each bowl with a few drops of high-quality extra virgin olive oil right before serving."]', '["If you plan on having leftovers, cook the pasta separately on the stove and add it directly to individual bowls. Pasta left sitting in the slow cooker will absorb broth and turn mushy overnight.","The Parmesan rind is a traditional Italian secret: as it simmers in the broth, it releases deep umami without melting into a clump."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Slow simmering allows the sweet aromatics (onions, carrots, celery) to melt into the crushed tomatoes and vegetable broth, developing the rich flavor of an all-day Italian stew without constant stirring. Adding quick-cooking zucchini, spinach, and pasta near the end preserves their fresh texture and vibrant color.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
