INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'homestyle-beef-stew', 'Homestyle Beef Stew Recipe (Slow Cooker Version)', NULL, 'Melt-in-your-mouth chuck roast cubes simmered with carrots, baby potatoes, and peas in a rich red wine and herb broth.', NULL, 'beef-pork', '["beef","beef stew","slow cooker","comfort food","soups and stews"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Rich beef stew with fork-tender beef, baby potatoes, and thick gravy in a ceramic bowl', '[]', 20, 480, NULL, 'Low 7 to 8 hours or High 4 to 5 hours',
  6, 'servings', '[{"quantity":2.5,"unit":"lb","item":"Beef chuck roast","note":"Trimmed of excess hard fat, cut into 1.5-inch cubes","scale":true},{"quantity":0.25,"unit":"cup","item":"All-purpose flour","note":"For dredging","scale":true},{"quantity":2,"unit":"tbsp","item":"Olive oil","note":"Divided","scale":true},{"quantity":1,"unit":"lb","item":"Baby yellow potatoes","note":"Halved","scale":true},{"quantity":4,"unit":"medium","item":"Carrots","note":"Peeled and sliced into 1-inch rounds","scale":true},{"quantity":2,"unit":"stalks","item":"Celery","note":"Sliced into 0.5-inch pieces","scale":true},{"quantity":1,"unit":"medium","item":"Yellow onion","note":"Chopped","scale":true},{"quantity":3,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":2,"unit":"cups","item":"Low-sodium beef broth","scale":true},{"quantity":0.5,"unit":"cup","item":"Dry red wine","note":"Cabernet or Merlot (substitute with additional broth if preferred)","scale":true},{"quantity":2,"unit":"tbsp","item":"Tomato paste","scale":true},{"quantity":1,"unit":"tbsp","item":"Worcestershire sauce","scale":true},{"quantity":1,"unit":"tsp","item":"Dried rosemary","note":"Crushed","scale":true},{"quantity":1,"unit":"tsp","item":"Dried thyme","scale":true},{"quantity":2,"unit":"leaves","item":"Bay leaves","scale":true},{"quantity":1.5,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.75,"unit":"tsp","item":"Coarse ground black pepper","scale":true},{"quantity":1,"unit":"cup","item":"Frozen peas","note":"Added in final 15 minutes","scale":true}]', '[{"title":"Step 1 – Sear the beef cubes","text":"Toss the beef cubes with the flour, 1 tsp salt, and 0.5 tsp pepper. Heat olive oil in a heavy skillet over medium-high heat. Sear beef in batches for 2 to 3 minutes per side until a deep brown crust develops. Transfer seared beef into the slow cooker."},{"title":"Step 2 – Deglaze the skillet","text":"Pour the red wine into the hot skillet, scraping up all browned fond from the bottom with a wooden spoon. Stir in the tomato paste and Worcestershire sauce, then pour the mixture over the beef."},{"title":"Step 3 – Add vegetables and broth","text":"Add the potatoes, carrots, celery, onion, and minced garlic into the slow cooker. Pour the beef broth over everything. Tuck the bay leaves, crushed rosemary, and thyme into the liquid."},{"title":"Step 4 – Slow cook until fork-tender","text":"Cover and cook on Low for 7 to 8 hours (or High for 4 to 5 hours). The beef should yield effortlessly to a fork, reaching around 200°F (93°C) internally where tough collagen fully dissolves into gelatin."},{"title":"Step 5 – Finish with peas","text":"Discard the bay leaves. Stir in the frozen green peas during the final 15 minutes of cooking. Taste and adjust salt and pepper before ladling into bowls."}]', '["Serve in warm deep ceramic bowls alongside thick slices of toasted sourdough or warm buttermilk biscuits.","Garnish with fresh chopped Italian parsley."]', '["Always choose bone-in or well-marbled chuck roast. Pre-cut ''stew meat'' from grocery stores often mixes lean cuts like round that end up dry and tough.","Browning the beef in a skillet takes just 8 minutes but builds the foundation of the deep, rich gravy flavor."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Chuck roast is loaded with connective collagen. Over 7 to 8 hours on low heat, that tough collagen breaks down into rich, natural gelatin that coats the meat fibers and thickens the broth naturally. Searing the floured beef first locks in roasty Maillard depth that a raw dump-and-cook method simply cannot match.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
