INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'juicy-slow-cooker-turkey-breast', 'Juicy Slow Cooker Turkey Breast', NULL, 'A tender, herb-butter basted boneless or bone-in turkey breast cooked in the crockpot without drying out. Easy holiday flavor for weeknight dinners.', NULL, 'easy-dinners', '["turkey","poultry","slow cooker","holiday meal","easy dinners"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Sliced herb butter slow cooker turkey breast on an oval carving platter', '[]', 15, 300, NULL, 'Low 5 to 6 hours (Low setting strongly recommended)',
  6, 'servings', '[{"quantity":5,"unit":"lb","item":"Bone-in or boneless turkey breast","note":"Thawed completely, skin on","scale":true},{"quantity":1,"unit":"large","item":"Yellow onion","note":"Cut into wedges","scale":true},{"quantity":2,"unit":"stalks","item":"Celery","note":"Cut into 2-inch pieces","scale":true},{"quantity":4,"unit":"tbsp","item":"Unsalted butter","note":"Softened to room temperature","scale":true},{"quantity":3,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":1,"unit":"tbsp","item":"Chopped fresh rosemary","note":"Or 1 tsp dried","scale":true},{"quantity":1,"unit":"tbsp","item":"Chopped fresh sage","note":"Or 1 tsp dried","scale":true},{"quantity":1,"unit":"tbsp","item":"Chopped fresh thyme","note":"Or 1 tsp dried","scale":true},{"quantity":1.5,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Freshly ground black pepper","scale":true},{"quantity":0.75,"unit":"cup","item":"Low-sodium chicken or turkey broth","scale":true}]', '[{"title":"Step 1 – Set up the aromatic bed","text":"Place the onion wedges and celery pieces across the bottom of the slow cooker insert to elevate the turkey breast off the base."},{"title":"Step 2 – Whip the garlic herb butter","text":"In a small bowl, mash the softened butter together with the minced garlic, rosemary, sage, thyme, salt, and black pepper until completely blended."},{"title":"Step 3 – Rub under and over the skin","text":"Pat the turkey breast thoroughly dry with paper towels. Gently separate the skin from the meat with your fingers and rub half the herb butter directly onto the meat under the skin. Spread the remaining butter over the top of the skin."},{"title":"Step 4 – Slow cook to 165°F","text":"Pour the broth into the bottom of the cooker around the vegetables. Set the turkey breast skin-side up on the onions. Cover and cook on Low for 5 to 6 hours until an instant-read meat thermometer inserted into the thickest part reads 165°F (74°C)."},{"title":"Step 5 – Broil and rest","text":"Transfer the cooked turkey breast to a baking sheet. Broil on high for 3 to 4 minutes to crisp and brown the buttered skin. Tent loosely with foil and rest for 15 minutes before carving across the grain."}]', '["Strain the rich onion-herb juices from the cooker basin, simmer in a small saucepan, and whisk with a tablespoon of flour for silky turkey gravy.","Serve with cranberry orange sauce, roasted green beans, and fluffy mashed potatoes."]', '["Never cook frozen poultry in a slow cooker. Always thaw turkey breast in the refrigerator for 24 to 48 hours prior to cooking.","Take the temperature from the deepest point of the meat, avoiding the breast bone. Pull at 165°F to ensure it stays succulent rather than chalky."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Whole turkeys often suffer from overcooked breast meat while waiting for the dark legs to finish. Cooking just the turkey breast in a slow cooker eliminates this mismatch entirely. Elevating the breast over onions allows the gentle steam and herb butter to baste the meat continuously, resulting in remarkably tender slices every time.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
