INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'melt-in-your-mouth-pork-fillet', 'Melt-in-Your-Mouth Pork Fillet Recipe', NULL, 'Whole pork tenderloin (pork fillet) slow-cooked in a balsamic honey, garlic, and soy glaze until exceptionally tender and juicy.', NULL, 'beef-pork', '["pork","pork tenderloin","pork fillet","slow cooker","easy dinners"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Sliced slow cooker pork fillet drizzled with glossy honey balsamic glaze', '[]', 10, 180, NULL, 'Low 2.5 to 3 hours (do not overcook)',
  4, 'servings', '[{"quantity":2,"unit":"lb","item":"Pork tenderloins (pork fillets)","note":"Trimmed of silver skin (about two 1-lb fillets)","scale":true},{"quantity":0.33,"unit":"cup","item":"Low-sodium soy sauce","scale":true},{"quantity":0.33,"unit":"cup","item":"Balsamic vinegar","scale":true},{"quantity":0.25,"unit":"cup","item":"Honey","scale":true},{"quantity":4,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":1,"unit":"tbsp","item":"Olive oil","scale":true},{"quantity":1,"unit":"tsp","item":"Dried rosemary","note":"Crushed","scale":true},{"quantity":0.5,"unit":"tsp","item":"Dried thyme","scale":true},{"quantity":0.75,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Black pepper","scale":true},{"quantity":1.5,"unit":"tbsp","item":"Cornstarch","note":"Mixed with 2 tbsp cold water","scale":true}]', '[{"title":"Step 1 – Trim and season the pork","text":"Remove any white silver skin membrane from the surface of the pork tenderloins with a sharp knife. Pat dry and rub with the salt, black pepper, rosemary, and thyme."},{"title":"Step 2 – Quick sear (optional for extra flavor)","text":"Heat olive oil in a skillet over high heat. Sear each tenderloin for 1 to 2 minutes per side until lightly browned on the outside. Transfer into the slow cooker."},{"title":"Step 3 – Mix the glaze","text":"In a bowl, whisk together the soy sauce, balsamic vinegar, honey, and minced garlic. Pour the glaze directly over the pork in the slow cooker."},{"title":"Step 4 – Slow cook on Low","text":"Cover and cook strictly on Low for 2.5 to 3 hours. Insert a meat thermometer into the thickest center: pull the pork the moment it registers 145°F (63°C). A light blush of pink in the center is safe and ensures maximum juiciness."},{"title":"Step 5 – Glaze and slice","text":"Transfer the tenderloins to a cutting board, tent with foil, and rest for 10 minutes. Pour the pan juices into a small saucepan, whisk in the cornstarch slurry, and simmer for 2 minutes until glossy and thick. Slice pork into 0.5-inch medallions and spoon the warm glaze over top."}]', '["Serve the glazed pork medallions over creamy garlic mashed potatoes or roasted sweet potato wedges.","Pairs wonderfully with steamed green beans or roasted asparagus."]', '["Pork tenderloin (fillet) is the most tender cut on the pig, but it has almost no fat. Cooking it beyond 3 hours or on High will make it tough. Always use a thermometer and aim for 145°F.","Resting the meat for 10 minutes before slicing is crucial to allow the internal juices to redistribute so they don''t pool onto the cutting board."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Pork tenderloin is an extremely lean muscle that requires precise timing rather than all-day stewing. Cooking it on Low for just under 3 hours in a sweet-and-tangy honey balsamic braise allows the meat to reach a juicy 145°F while absorbing rich umami depth without becoming dry or chalky.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
