INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'slow-cooker-beef-chili', 'Easy Slow Cooker Beef Chili', NULL, 'A hearty and comforting slow cooker beef chili packed with beans, tomatoes, and the perfect blend of spices. Perfect for easy weeknight dinners.', NULL, 'beef-pork', '["beef","chili","slow cooker","dinner"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793344445/crockbites/recipes/ova0tx0mwaeejpzs6qgo.jpg', 'Easy Slow Cooker Beef Chili', '[{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793344445/crockbites/recipes/ova0tx0mwaeejpzs6qgo.jpg","publicId":"crockbites/recipes/ova0tx0mwaeejpzs6qgo","alt":"Easy Slow Cooker Beef Chili","width":2528,"height":1696,"isPrimary":true}]', 15, 360, NULL, '6 to 8 hours on LOW or 3 to 4 hours on HIGH',
  6, 'servings', '[{"quantity":1.5,"unit":"lb","item":"Lean ground beef","scale":true},{"quantity":1,"unit":"medium","item":"Yellow onion","note":"Chopped","scale":true},{"quantity":2,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":1,"unit":"can (15 oz)","item":"Kidney beans","note":"Drained and rinsed","scale":true},{"quantity":1,"unit":"can (28 oz)","item":"Crushed tomatoes","scale":true},{"quantity":2,"unit":"tbsp","item":"Chili powder","scale":true},{"quantity":1,"unit":"tsp","item":"Ground cumin","scale":true},{"quantity":1,"unit":"tsp","item":"Salt","note":"To taste","scale":true}]', '[{"title":"Brown the beef","text":"In a skillet over medium-high heat, cook the ground beef and chopped onions until the beef is browned (reaching at least 160°F / 71°C) and the onions are tender. Drain excess fat."},{"title":"Combine in slow cooker","text":"Transfer the browned beef and onions to the slow cooker. Add the minced garlic, drained kidney beans, crushed tomatoes, chili powder, ground cumin, and salt."},{"title":"Mix and cook","text":"Stir all the ingredients together until well combined. Cover and cook on LOW for 6 to 8 hours, or on HIGH for 3 to 4 hours."},{"title":"Garnish and serve","text":"Stir well before serving. Ladle into bowls and serve hot with your favorite toppings."}]', '[]', '[]', '[]',
  '{}', '[]', '["Cook ground beef to a minimum safe internal temperature of 160°F (71°C), verified with an instant-read food thermometer.","Refrigerate leftover chili in shallow airtight containers within 2 hours of cooking, and reheat leftovers to 165°F (74°C)."]', '["gluten-free","dairy-free","high-protein"]', 1, '[]', 1,
  'Prepared with ground beef, beans, tomatoes, and pure spices. Check canned bean and spice labels if serving someone sensitive to facility cross-contact, and note that optional dairy toppings (such as cheddar or sour cream) contain Milk.', NULL, 0, NULL, '[]', 1, 'tested',
  '', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
