  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'sri-lankan-pol-sambol-traditional-coconut-sambol', 'Sri Lankan Pol Sambol (Traditional Coconut Sambol)', NULL, 'A traditional Sri Lankan pol sambol made with freshly grated coconut, red onions, chillies, and fresh lime juice, with optional traditional Maldive fish. A spicy, tangy side dish full of authentic island flavour.', NULL, 'breakfast', '["sri lankan food","pol sambol","coconut sambol","traditional sri lankan recipes","vegetarian side dish","coconut recipes","spicy food"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/qr5lj1taqlcfipydcryf.jpg', 'Traditional Coconut Sambol', '[{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/qr5lj1taqlcfipydcryf.jpg","publicId":"crockbites/recipes/qr5lj1taqlcfipydcryf","alt":"Traditional Coconut Sambol","width":554,"height":554,"isPrimary":true},{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337883/crockbites/recipes/owlkdjwpjvbh0vpbh4l9.jpg","publicId":"crockbites/recipes/owlkdjwpjvbh0vpbh4l9","alt":"Serve fresh","width":840,"height":559,"isPrimary":false},{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337884/crockbites/recipes/iyptxxdauncthox64uxy.jpg","publicId":"crockbites/recipes/iyptxxdauncthox64uxy","alt":"Add lime juice","width":768,"height":512,"isPrimary":false},{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337885/crockbites/recipes/qokpnyrallilbtx81gb7.jpg","publicId":"crockbites/recipes/qokpnyrallilbtx81gb7","alt":"Mix the coconut","width":640,"height":640,"isPrimary":false},{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337886/crockbites/recipes/jqptiupnowiuzo9mnuqa.jpg","publicId":"crockbites/recipes/jqptiupnowiuzo9mnuqa","alt":"Crush the spices","width":1236,"height":1536,"isPrimary":false},{"url":"https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337888/crockbites/recipes/vrzzbacmpmpz13zqe46t.jpg","publicId":"crockbites/recipes/vrzzbacmpmpz13zqe46t","alt":"Prepare the ingredients","width":1920,"height":1080,"isPrimary":false}]', 15, 0, NULL, NULL,
  4, 'servings', '[{"quantity":2,"unit":"cup","item":"Freshly grated coconut","note":"Fresh coconut is best","scale":true},{"quantity":1,"unit":"medium","item":"Red onion","note":"Finely chopped","scale":true},{"quantity":2,"item":"Green or dried red chillies","note":"Adjust to taste","scale":true},{"quantity":1,"unit":"tsp","item":"Chilli powder","note":"Adjust spice level","scale":true},{"quantity":0.5,"unit":"tsp","item":"Salt","note":"To taste","scale":true},{"quantity":1,"unit":"tbsp","item":"Lime juice","note":"Freshly squeezed","scale":true},{"quantity":1,"unit":"pinch","item":"Black pepper","note":"Optional","scale":true}]', '[{"title":"Prepare the ingredients","text":"Grate the fresh coconut and finely chop the red onion. Slice the chillies (and prepare 1 tablespoon of crushed Maldive fish flakes only if making the non-vegan coastal variation)."},{"title":"Crush the aromatics and spices","text":"In a mortar and pestle or bowl, lightly crush the chillies, chilli powder, salt, and chopped red onion so the onion juices release and coat the spices."},{"title":"Mix in the coconut and lime juice","text":"Add the freshly grated coconut, fresh lime juice, and optional black pepper. Mix and gently press everything together with your fingertips or a spoon until evenly combined and vibrant orange-red. Taste and adjust salt, chilli, or lime."},{"title":"Serve fresh","text":"Transfer the pol sambol to a serving bowl and serve immediately with rice and curry, string hoppers, hoppers, kiribath, or warm roti."}]', '[]', '[]', '[]',
  '{}', '[]', '[]', '["vegetarian","vegan","gluten-free","dairy-free"]', 1, '[]', 1,
  'The base recipe above is 100% plant-based, vegan, and fish-free. If you add optional traditional Maldive fish (umbalakada), the dish will contain Fish allergen and will no longer be vegetarian or vegan.', NULL, 0, NULL, '[]', 1, 'tested',
  '', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
