INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'tender-pork-loin-chops', 'Tender Pork Loin Chops Slow Cooker Recipe', NULL, 'Thick-cut pork loin chops simmered in a savory apple cider and Dijon herb sauce until tender and moist without drying out.', NULL, 'beef-pork', '["pork","pork chops","slow cooker","easy dinners","weeknight"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Tender slow cooker pork chops coated in savory herb Dijon pan sauce', '[]', 15, 240, NULL, 'Low 4 to 5 hours (do not cook on High)',
  4, 'servings', '[{"quantity":4,"unit":"thick-cut","item":"Bone-in or boneless pork loin chops","note":"About 1 inch thick, roughly 2 lbs total","scale":true},{"quantity":1,"unit":"large","item":"Yellow onion","note":"Sliced into half-moons","scale":true},{"quantity":2,"unit":"cloves","item":"Garlic","note":"Minced","scale":true},{"quantity":0.75,"unit":"cup","item":"Low-sodium chicken broth","scale":true},{"quantity":0.25,"unit":"cup","item":"Apple cider or unsweetened apple juice","scale":true},{"quantity":2,"unit":"tbsp","item":"Dijon mustard","scale":true},{"quantity":1,"unit":"tbsp","item":"Worcestershire sauce","scale":true},{"quantity":1,"unit":"tsp","item":"Dried thyme","scale":true},{"quantity":1,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Fresh ground black pepper","scale":true},{"quantity":1.5,"unit":"tbsp","item":"Cornstarch","note":"Mixed with 2 tbsp cold water for gravy","scale":true}]', '[{"title":"Step 1 – Layer the onions","text":"Scatter the sliced onions and minced garlic evenly across the bottom of the slow cooker basin."},{"title":"Step 2 – Season the chops","text":"Pat the pork chops dry with clean paper towels. Season both sides generously with kosher salt, black pepper, and dried thyme."},{"title":"Step 3 – Whisk the braising liquid","text":"In a measuring cup, whisk together the chicken broth, apple cider, Dijon mustard, and Worcestershire sauce until smooth. Pour half the mixture over the onions."},{"title":"Step 4 – Arrange and cook","text":"Lay the pork chops in a single layer over the onion bed, then drizzle the remaining sauce over the meat. Cover and cook on Low for 4 to 5 hours. Avoid High setting, which can toughen lean loin cuts."},{"title":"Step 5 – Thicken the pan sauce","text":"Pork chops are safely done when an instant-read thermometer reaches 145°F (63°C) in the thickest section. Transfer chops to a platter. Whisk the cornstarch slurry into the hot cooker juices, cover, and let cook on high for 10 minutes until thick and glossy. Spoon over chops to serve."}]', '["Spoon the savory Dijon onion gravy over buttered egg noodles or garlic mashed potatoes.","Pair with roasted Brussels sprouts or warm applesauce for a balanced plate."]', '["Use chops that are at least 1-inch thick. Thin breakfast pork chops cook too fast and turn stringy in a slow cooker.","Low and slow is mandatory for pork loin: it has minimal intramuscular fat, so cooking on Low keeps the fibers relaxed and juicy."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Pork loin is notoriously lean, meaning high heat quickly dries it out. By cooking 1-inch thick chops on Low in a moist, acidic braise of apple cider and Dijon mustard, the muscle fibers gently relax without seizing. Finishing with a quick slurry turns the savory cooking juices into a rich pan sauce.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
