INSERT INTO recipes (
  slug, title, seo_title, description, seo_description, category, tags, author,
  image_url, image_alt, gallery, prep_minutes, cook_minutes, total_minutes, cook_time_note,
  servings, servings_label, ingredients, instructions, serving_suggestions, tips, substitutions,
  storage, equipment, food_safety, dietary_labels, dietary_verified, allergens, allergen_reviewed,
  allergen_notes, nutrition, featured, popular_rank, related, notify_newsletter, review_status,
  body, pub_date, updated_date, created_at, updated_at
) VALUES (
  'ultimate-slow-cooker-chicken', 'Ultimate Slow Cooker Chicken (Easy Everyday Recipe)', NULL, 'Juicy, fall-apart whole chicken cooked right in the slow cooker with garlic, paprika, and herbs. Simple prep with rich pan juices for easy gravy.', NULL, 'slow-cooker-chicken', '["chicken","whole chicken","slow cooker","easy dinners","weeknight"]', 'CrockBites',
  'https://res.cloudinary.com/dmxumqqpj/image/upload/v1793337810/crockbites/recipes/placeholder.jpg', 'Slow cooked whole chicken with crisp herb skin resting on a wooden board', '[]', 15, 300, NULL, 'Low 5 to 6 hours or High 3 to 4 hours',
  6, 'servings', '[{"quantity":4.5,"unit":"lb","item":"Whole chicken","note":"Giblets removed, patted thoroughly dry","scale":true},{"quantity":1,"unit":"large","item":"Yellow onion","note":"Thickly sliced","scale":true},{"quantity":4,"unit":"cloves","item":"Garlic","note":"Smashed","scale":true},{"quantity":1,"unit":"tbsp","item":"Olive oil","scale":true},{"quantity":1,"unit":"tbsp","item":"Smoked paprika","scale":true},{"quantity":1,"unit":"tsp","item":"Garlic powder","scale":true},{"quantity":1,"unit":"tsp","item":"Dried thyme","scale":true},{"quantity":1,"unit":"tsp","item":"Dried oregano","scale":true},{"quantity":1.5,"unit":"tsp","item":"Kosher salt","scale":true},{"quantity":0.5,"unit":"tsp","item":"Coarse black pepper","scale":true},{"quantity":0.5,"unit":"cup","item":"Low-sodium chicken broth","scale":true}]', '[{"title":"Step 1 – Build the vegetable base","text":"Place the thick onion slices and smashed garlic cloves across the bottom of the slow cooker. This props the chicken up so it roasts rather than boils in its juices."},{"title":"Step 2 – Season the bird","text":"Pat the chicken completely dry with paper towels. Rub olive oil all over the skin. In a small bowl, mix the paprika, garlic powder, thyme, oregano, salt, and pepper, then rub the spice mixture evenly across the entire chicken."},{"title":"Step 3 – Set in the cooker","text":"Pour the chicken broth gently around the base of the cooker without washing the spice rub off the top. Place the chicken breast-side up on top of the onions."},{"title":"Step 4 – Cook to temperature","text":"Cover and cook on Low for 5 to 6 hours (or High for 3 to 4 hours). Check that the thickest part of the thigh registers at least 165°F (74°C) on an instant-read meat thermometer."},{"title":"Step 5 – Rest and crisp","text":"Carefully transfer the chicken to a rimmed baking sheet. For crispy skin, pop under your oven broiler on high for 3 to 5 minutes. Rest 10 minutes before carving."}]', '["Skim the pan juices from the slow cooker and whisk with a tablespoon of cornstarch over medium heat for quick homemade gravy.","Serve with creamy mashed potatoes and buttered steamed green beans."]', '["Always check doneness with a meat thermometer. Time varies by cooker size, but 165°F in the inner thigh away from bone guarantees tender, safe meat.","Puffed crumpled foil balls can also be placed under the chicken if you prefer to keep it even higher above the rendered juices."]', '[]',
  '{}', '[]', '[]', '[]', 0, '[]', 0,
  NULL, NULL, 0, NULL, '[]', 1, 'draft',
  '### Why This Recipe Works
Slow cooking a whole chicken traps moisture so the breast meat stays tender instead of drying out. The onion trivet keeps the bottom from stewing in rendered liquid, while a quick 3-minute oven broil at the end gives you the golden, crackling skin of a traditional roasted chicken with none of the weekday stress.', '2026-10-30', NULL, '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z'
) ON CONFLICT(slug) DO UPDATE SET
